import bisect
from collections import defaultdict

aborts=[]
with open('/root/traces/aborts.tsv') as f:
    for line in f:
        if line.strip():
            t,k,lw,cw,cts,ats=line.split('\t')
            aborts.append((int(t),int(k),int(lw),int(cw),int(cts)))

same=sum(1 for _,_,lw,cw,_ in aborts if lw==cw)
diff=len(aborts)-same
print('abort rows',len(aborts),'same_wts',same,'diff_wts',diff)

# Load writes for abort keys
keys={k for _,k,_,_,_ in aborts}
wts=defaultdict(list)
with open('/root/traces/writes.tsv') as f:
    for line in f:
        if not line.strip():
            continue
        _,k,nw,_=line.split('\t')
        k=int(k)
        if k in keys:
            wts[k].append(int(nw))
for k in list(wts):
    wts[k]=sorted(set(wts[k]))

unnecessary_same=0
unnecessary_diff=0
necessary_diff=0
for t,k,lw,cw,cts in aborts:
    if lw==cw:
        unnecessary_same+=1
    else:
        lst=wts[k]
        i=bisect.bisect_right(lst,lw)
        next_wts=lst[i] if i<len(lst) else cw
        if cts<next_wts:
            unnecessary_diff+=1
        else:
            necessary_diff+=1
print('unnecessary due to same_wts',unnecessary_same)
print('unnecessary due to diff_wts but early commit_ts',unnecessary_diff)
print('necessary diff_wts',necessary_diff)
